506			application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
507			serviceWorkers: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
508			byteIdentical: true;
509			hmrControls: false;
510			legacyMainPrecache:
511				| {
512						state: 'exact-completed';
513						responses: Array<{
514							method: 'GET';
515							pathname: string;
516							query: '?__uncache=versionless-deterministic';
517							destination: 'empty';
518							resolvedFile: string;
519							status: 200;
520							mime: string;
521							bytes: number;
522							sha256: string;
523							urlPath: string;
524							source: 'production-static-origin';
525						}>;
526				  }
527				| { state: 'not-applicable' };
528			phonecatOrdering:
529				| {
530						state: 'data-derived-full-order';
531						datasetSha256: string;
532						orderSha256: string;
533						rows: 20;
534						comparator: 'stable-lowercase-utf16-source-order-ties';
535				  }
536				| { state: 'not-applicable' };
537			phonecatImageTransition:
538				| {
539						state: 'data-derived-visible-transition';
540						detailSha256: string;
541						defaultImage: string;
542						nonDefaultImage: string;
543						hover: 'genuine-thumbnail-mouseover';
544						transition: 'genuine-ng-click';
545						heroVisibility: 'genuine-hover';
546				  }
547				| { state: 'not-applicable' };
548			nextPrerenderPayload?: WitnessNextPrerenderPayloadEvidence;
549		};
550		observerFinalization: {
551			state: 'target-closed';
552			detach: 'owned-detach-complete';
553			pageClose: 'owned-page-close-complete';
554			workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
555		};
556		semanticDigest: string;
557		successfulNonLoopback: 0;
558		consoleErrorInventory?: WitnessConsoleErrorInventory;
559		failedRequestInventory?: WitnessFailedRequestInventory;
560		cancelledDuplicateFetches?: WitnessCancelledDuplicateFetchInventory;
561		mockedNonLoopbackSeams?: WitnessMockedNonLoopbackSeamInventory;
562		/**
563		 * Present exactly when the application declared a file-input surface. Its
564		 * absence is the evidence that this run's page was never handed a file.
565		 */
566		fileInputLoads?: WitnessFileInputLoadInventory;
567		/**
568		 * Present exactly when the application declared that it produces downloads.
569		 * Its absence is the evidence that this run's browser context refused them.
570		 */
571		downloadCaptures?: WitnessDownloadCaptureInventory;
572		renderedStyles?: WitnessRenderedStyleEvidence;
573		applicationJourney?: WitnessApplicationJourneyEvidence;
574		scrollSurface?: WitnessScrollSurface;
575		scrollAbsence?: WitnessMeasuredScrollAbsence;
576	};
577	
578	/**
579	 * Measured scroll evidence for one route that genuinely overflows the stated
580	 * viewport. The document extents are read from the live page, and the scroll
581	 * itself is a real wheel gesture the browser driver confirms moved the
582	 * viewport — the boolean is an observation, not a claim substituted for one.
583	 */
584	export type WitnessScrollSurface = {
585		state: 'measured-genuine-viewport-scroll';
586		route: string;
587		viewport: { width: number; height: number };
588		scrollHeight: number;
589		clientHeight: number;
590		wheelDeltaY: number;
591		scrolledFromTop: true;
592		scrolled: true;
593	};
594	
595	/**
596	 * The measured counterpart of {@link WitnessScrollSurface}: evidence that a
597	 * journey looked for a scroll surface and did not find one.
598	 *
599	 * An application that pins its document to the viewport and scrolls its own
600	 * inner panels instead has no scrollable document to gesture at, and inventing
601	 * one would be a false claim. So the same generic measurement that backs a
602	 * scroll claim is taken at every visited route and recorded here instead:
603	 * `scrollHeight` never exceeds `clientHeight`, which is why no scroll coverage
604	 * is claimed. Routes are recorded individually rather than summarized, so a
605	 * route that starts overflowing later cannot hide inside a total.
606	 */
607	export type WitnessMeasuredScrollAbsence = {
608		state: 'measured-no-overflowing-document';
609		viewport: { width: number; height: number };
610		routes: Array<{ route: string; scrollHeight: number; clientHeight: number }>;
611		/** How the application keeps the document from overflowing, observed rather than assumed. */
612		documentOverflow: string;
613		claimed: false;
614	};
615	
616	export type WitnessMutationProof = {
617		app: 'react-boilerplate' | 'angular-realworld';
618		failure: 'witness-semantic-assertion';
619		intendedFailure: true;
620		restoredByteIdentically: true;
621	};
622	
623	export type WitnessRealAppReceipt = {
624		schemaVersion: typeof WITNESS_REAL_APP_SCHEMA;
625		result: 'pass';
626		provenance: Record<string, unknown>;
627		canonicalReceipts: Array<{
628			app: string;
629			path: string;
630			sha256: string;
631			canonicalDigest: string;
632		}>;
633		runs: WitnessRealAppRun[];
634		mutations: WitnessMutationProof[];
635		killedByGoogleInventory: {
636			archiveSha256: string;
637			mirrorFiles: number;
638			sourceFiles: Record<'baseline' | 'migrated', number>;
639			buildFiles: Record<'baseline' | 'migrated', number>;
640			transformEdits: 3;
641		};
642		locality: { mode: 'offline'; successfulNonLoopback: 0; osWideIsolation: false };
643		nonclaims: string[];
644		integrity: { algorithm: 'sha256'; canonicalDigest: string };
645	};
646	
647	function record(value: unknown, label: string): Record<string, unknown> {
648		if (value === null || typeof value !== 'object' || Array.isArray(value))
649			throw new Error(`Witness real-app ${label} must be an object`);
650		return value as Record<string, unknown>;
651	}
652	
653	function sha256Digest(value: unknown): value is string {
654		return typeof value === 'string' && value.length === 64;
655	}
656	
657	function sortedUniqueStrings(values: unknown): values is string[] {
658		return (
659			Array.isArray(values) &&
660			values.every((value) => typeof value === 'string') &&
661			new Set(values).size === values.length &&
662			values.join('\n') === [...values].sort().join('\n')
663		);
664	}
665	
666	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
667		const telemetry = value as WitnessServiceWorkerTelemetry;
668		return (
669			telemetry?.state === 'ready' &&
670			telemetry.registration?.scriptPath === '/sw.js' &&
671			telemetry.registration.scope === '/' &&
672			telemetry.registration.active === 'activated' &&
673			(telemetry.controller === 'activated' || telemetry.controller === null) &&
674			sortedUniqueStrings(telemetry.cacheNames) &&
675			telemetry.cacheNames.length === 1 &&
676			Array.isArray(telemetry.cacheEntries) &&
677			telemetry.cacheEntries.length === 1 &&
678			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
679			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
680			telemetry.cacheEntries[0].paths.length > 0 &&
681			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
682			Array.isArray(telemetry.workerEvents)
683		);
684	}
685	
686	export function witnessRealAppDigest(receipt: WitnessRealAppReceipt): string {
687		const copy = structuredClone(receipt);
688		copy.integrity.canonicalDigest = '';
689		return sha256(canonicalize(copy));
690	}
691	
692	export function parseWitnessRealAppReceipt(value: unknown): WitnessRealAppReceipt {
693		const receipt = record(value, 'receipt') as WitnessRealAppReceipt;
694		if (
695			receipt.schemaVersion !== WITNESS_REAL_APP_SCHEMA ||
696			receipt.result !== 'pass' ||
697			!Array.isArray(receipt.runs) ||
698			receipt.runs.length !== WITNESS_REAL_APP_RUNS ||
699			!Array.isArray(receipt.canonicalReceipts) ||
700			receipt.canonicalReceipts.length !== WITNESS_REAL_APP_NAMES.length
701		)
702			throw new Error('Witness real-app receipt cardinality differs');
703		const expected = new Set<string>();
704		for (const app of WITNESS_REAL_APP_NAMES)
705			for (const lane of ['baseline', 'migrated'])
706				for (const pass of [1, 2]) expected.add(`${app}:${lane}:${pass}`);
707		const gestures = new Set<WitnessGesture>();
708		const semanticPasses = new Map<string, string>();
709		for (const run of receipt.runs) {
710			const key = `${run.app}:${run.lane}:${run.pass}`;
711			const served = run.servedStatic;
712			const servedStaticDiffers =
713				served?.transport !== 'isolated-bounded-loopback-production-static' ||
714				served.documentFallback !== 'index-only' ||
715				served.missingAssets !== '404' ||
716				served.traversal !== 'rejected' ||
717				!Number.isInteger(served.inventory?.files) ||
718				served.inventory.files < 1 ||
719				!sha256Digest(served.inventory.beforeSha256) ||
720				served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
721				served.application?.path !== 'index.html' ||
722				!sha256Digest(served.application.beforeSha256) ||
723				served.application.beforeSha256 !== served.application.afterSha256 ||
724				!Array.isArray(served.serviceWorkers) ||
725				served.serviceWorkers.some(
726					(serviceWorker) =>
727						serviceWorker.path !== 'sw.js' ||
728						!sha256Digest(serviceWorker.beforeSha256) ||
729						serviceWorker.beforeSha256 !== serviceWorker.afterSha256,
730				) ||
731				(run.app === 'react-boilerplate'
732					? served.serviceWorkers.length !== 1
733					: served.serviceWorkers.length !== 0) ||
734				served.byteIdentical !== true ||
735				served.hmrControls !== false;
736			const expectedLegacyMain = [
737				['/favicon.ico', 'favicon.ico', 'image/x-icon'],
738				[
739					'/2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
740					'2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
741					'image/jpeg',
742				],
743				[
744					'/runtime.bfb7866e5bd316b6a048.js',
745					'runtime.bfb7866e5bd316b6a048.js',
746					'text/javascript',
747				],
748				['/', 'index.html', 'text/html'],
749			] as const;
750			const legacyMainPrecacheDiffers =
751				run.app === 'react-boilerplate' && run.lane === 'baseline'
752					? served.legacyMainPrecache?.state !== 'exact-completed' ||
753						served.legacyMainPrecache.responses.length !== expectedLegacyMain.length ||
754						served.legacyMainPrecache.responses.some((response, index) => {
755							const expectedResponse = expectedLegacyMain[index];
756							return (
757								expectedResponse === undefined ||
758								response.method !== 'GET' ||
759								response.pathname !== expectedResponse[0] ||
760								response.query !== '?__uncache=versionless-deterministic' ||
761								response.destination !== 'empty' ||
762								response.resolvedFile !== expectedResponse[1] ||
763								response.status !== 200 ||
764								response.mime !== expectedResponse[2] ||
765								!Number.isInteger(response.bytes) ||
766								response.bytes < 1 ||
767								!sha256Digest(response.sha256) ||
768								response.urlPath !== `${response.pathname}${response.query}` ||
769								response.source !== 'production-static-origin'
770							);
771						})
772					: served.legacyMainPrecache?.state !== 'not-applicable';
773			const phonecatOrderingDiffers =
774				run.app === 'angular-phonecat'
775					? served.phonecatOrdering?.state !== 'data-derived-full-order' ||
776						!sha256Digest(served.phonecatOrdering.datasetSha256) ||
777						!sha256Digest(served.phonecatOrdering.orderSha256) ||
778						served.phonecatOrdering.rows !== 20 ||
779						served.phonecatOrdering.comparator !==
780							'stable-lowercase-utf16-source-order-ties'
781					: served.phonecatOrdering?.state !== 'not-applicable';
782			const phonecatImageTransitionDiffers =
783				run.app === 'angular-phonecat'
784					? served.phonecatImageTransition?.state !== 'data-derived-visible-transition' ||
785						!sha256Digest(served.phonecatImageTransition.detailSha256) ||
786						!served.phonecatImageTransition.defaultImage.startsWith('img/phones/') ||
787						!served.phonecatImageTransition.nonDefaultImage.startsWith('img/phones/') ||
788						served.phonecatImageTransition.defaultImage ===
789							served.phonecatImageTransition.nonDefaultImage ||
790						served.phonecatImageTransition.hover !== 'genuine-thumbnail-mouseover' ||
791						served.phonecatImageTransition.transition !== 'genuine-ng-click' ||
792						served.phonecatImageTransition.heroVisibility !== 'genuine-hover'
793					: served.phonecatImageTransition?.state !== 'not-applicable';
794			const observerFinalizationDiffers =
795				run.observerFinalization?.state !== 'target-closed' ||
796				run.observerFinalization.detach !== 'owned-detach-complete' ||
797				run.observerFinalization.pageClose !== 'owned-page-close-complete' ||
798				!Array.isArray(run.observerFinalization.workerEvents);
799			const lifecycle =
800				run.offlineEvidence.state === 'react-shell-rendered-state-reset'
801					? run.offlineEvidence.lifecycle
802					: undefined;
803			const expectedCacheName =
804				run.lane === 'baseline'
805					? 'webpack-offline:versionless-deterministic'
806					: 'versionless-react-vite8-553cd1cc611a0851b1978bbc041ef2f8c7b9fbbd3fdd9bb68274f29364987cdc';
807			const lifecycleDiffers =
808				run.app === 'react-boilerplate'
809					? lifecycle?.state !== 'ready-online-reload-controlled-offline-reset' ||
810						!validServiceWorkerTelemetry(lifecycle.ready) ||
811						!validServiceWorkerTelemetry(lifecycle.controlled) ||
812						lifecycle.controlled.controller !== 'activated' ||
813						lifecycle.ready.cacheNames[0] !== expectedCacheName ||
814						canonicalize(lifecycle.ready.cacheEntries) !==
815							canonicalize(lifecycle.controlled.cacheEntries) ||
816						!sortedUniqueStrings(lifecycle.onlineStaticPaths) ||
817						!lifecycle.onlineStaticPaths.includes('/sw.js') ||
818						lifecycle.ready.cacheEntries[0]!.paths.some(
819							(path) =>
820								path !== '/__offline_webpack__data' &&
821								!lifecycle.onlineStaticPaths.includes(path),
822						) ||
823						lifecycle.offlineServerRequests !== 0
824					: lifecycle !== undefined;
825			if (
826				run.interactions.some((interaction) => interaction.kind === 'drag') &&
827				!(WITNESS_REAL_APP_DRAG_SURFACES as readonly string[]).includes(run.app)
828			)
829				throw new Error('Witness real-app drag must remain not-tested');
830			if (
831				!expected.delete(key) ||
832				run.result !== 'pass' ||
833				run.successfulNonLoopback !== 0 ||
834				!Array.isArray(run.interactions) ||
835				run.interactions.length === 0 ||
836				!Array.isArray(run.assertions) ||
837				run.assertions.length === 0 ||
838				servedStaticDiffers ||
839				legacyMainPrecacheDiffers ||
840				phonecatOrderingDiffers ||
841				phonecatImageTransitionDiffers ||
842				observerFinalizationDiffers ||
843				lifecycleDiffers ||
844				run.cleanPage !== true ||
845				(run.app === 'react-boilerplate'
846					? run.offlineEvidence?.state !== 'react-shell-rendered-state-reset' ||
847						run.offlineEvidence.shellRendered !== true ||
848						run.offlineEvidence.usernameReset !== true ||
849						run.offlineEvidence.repositoriesReset !== true ||
850						run.offlineEvidence.apiResponseCaching !== 'not-claimed' ||
851						run.offlineEvidence.reduxPersistence !== 'not-implemented' ||
852						run.offlineEvidence.priorResultPersistence !== 'not-implemented' ||
853						run.offlineEvidence.harnessFulfillment !==
854							'synthetic-github-route-online-only' ||
855						run.offlineEvidence.serviceWorkerEvidence?.source !== 'canonical-t060' ||
856						run.offlineEvidence.serviceWorkerEvidence.receiptPath !==
857							'evidence/runs/react-boilerplate-v4-composed/t060-run.json' ||
858						run.offlineEvidence.serviceWorkerEvidence.canonicalDigest !==
859							'52400147929220935a9ebe47a16c8dff50b5c28e9d51c930d000c99c2bdc8a21' ||
860						run.offlineEvidence.serviceWorkerEvidence.newProof !== false
861					: run.offlineEvidence?.state !== 'not-applicable') ||
862				run.semanticDigest !==
863					sha256(
864						canonicalize({
865							app: run.app,
866							framework: run.framework,
867							lane: run.lane,
868							interactions: run.interactions,
869							assertions: run.assertions,
870							routes: run.routes,
871							trackedEvents: run.trackedEvents,
872							witnessRecord: run.witnessRecord,
873							cleanPage: run.cleanPage,
874							offlineEvidence: run.offlineEvidence,
875							servedStatic: run.servedStatic,
876							observerFinalization: run.observerFinalization,
877							successfulNonLoopback: run.successfulNonLoopback,
878						}),
879					)
880			)
881				throw new Error(`Witness real-app run differs: ${key}`);
882			const pair = `${run.app}:${run.lane}`;
883			const prior = semanticPasses.get(pair);
884			if (prior !== undefined && prior !== run.semanticDigest)
885				throw new Error(`Witness real-app repeated pass differs: ${pair}`);
886			semanticPasses.set(pair, run.semanticDigest);
887			for (const interaction of run.interactions) {
888				gestures.add(interaction.kind);
889			}
890		}
891		if (
892			expected.size !== 0 ||
893			[...gestures].sort().join(',') !== 'click,drag,hover,press,scroll,type'
894		)
895			throw new Error('Witness real-app interaction coverage differs');
896		if (
897			receipt.mutations?.length !== 2 ||
898			receipt.mutations.some(
899				(mutation) =>
900					mutation.failure !== 'witness-semantic-assertion' ||
901					mutation.intendedFailure !== true ||
902					mutation.restoredByteIdentically !== true,
903			) ||
904			!receipt.mutations.some((mutation) => mutation.app === 'react-boilerplate') ||
905			!receipt.mutations.some((mutation) => mutation.app === 'angular-realworld') ||
906			receipt.killedByGoogleInventory?.transformEdits !== 3 ||
907			receipt.locality?.mode !== 'offline' ||
908			receipt.locality?.successfulNonLoopback !== 0 ||
909			receipt.locality?.osWideIsolation !== false ||
910			!receipt.nonclaims?.some((claim) => claim.includes('Drag is tested only')) ||
911			receipt.integrity?.algorithm !== 'sha256' ||
912			receipt.integrity.canonicalDigest !== witnessRealAppDigest(receipt)
913		)
914			throw new Error('Witness real-app receipt integrity or nonclaims differ');
915		return receipt;
916	}
