					canonicalize({
						app: run.app,
						framework: run.framework,
						lane: run.lane,
						interactions: run.interactions,
						assertions: run.assertions,
						routes: run.routes,
						trackedEvents: run.trackedEvents,
						witnessRecord: run.witnessRecord,
						cleanPage: run.cleanPage,
