		receipt.mutations?.length !== 2 ||
		receipt.mutations.some(
			(mutation) =>
				mutation.failure !== 'witness-semantic-assertion' ||
				mutation.intendedFailure !== true ||
				mutation.restoredByteIdentically !== true,
		) ||
