81	async function files(directory: string): Promise<string[]> {
82		const output: string[] = [];
83		for (const entry of await readdir(directory, { withFileTypes: true })) {
84			const path = join(directory, entry.name);
85			if (entry.isDirectory()) output.push(...(await files(path)));
86			else if (entry.isFile()) output.push(path);
