91	/** Every file of an emitted artifact, addressed exactly as the u19k record does. */
92	async function inventoryOf(rootDirectory: string): Promise<InventoryEntry[]> {
93		const entries: InventoryEntry[] = [];
94		for (const file of await files(rootDirectory)) {
95			const bytes = await readFile(file);
