105	/** The pinned migrated build record, re-read rather than restated. */
106	async function migratedLaneRecord(): Promise<{
107		inventory: InventoryEntry[];
108		inventorySha256: string;
109	}> {
110		const pinned = ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.find(
