130	 * JSON array with a trailing newline, exactly as the recording flow wrote it.
131	 * Recomputing it here rather than accepting the record's own number is what
132	 * makes the comparison a check instead of a restatement.
133	 */
134	function inventoryDigest(inventory: readonly InventoryEntry[]): string {
135		return sha256(`${JSON.stringify(inventory, null, 2)}\n`);
