138	async function run(command: string, args: readonly string[], cwd: string): Promise<void> {
139		await new Promise<void>((settle, fail) => {
140			const child = spawn(command, [...args], {
141				cwd,
142				stdio: 'ignore',
143				env: {
144					...process.env,
145					VERSIONLESS_NETWORK_MODE: 'offline',
146					NPM_CONFIG_OFFLINE: 'true',
147				},
148			});
149			child.on('error', fail);
150			child.on('close', (code) =>
151				code === 0
152					? settle()
153					: fail(new Error(`TinyTranslator regeneration command failed: ${command} (${code})`)),
154			);
155		});
156	}
