239	/**
240	 * Byte mutation on the migrated build.
241	 *
242	 * The seam is the visible label of the control that opens the file picker: a
243	 * string a reader sees, asserted exactly by the journey on the create-project
244	 * route, and the name of the very mechanism this vertical exists to exercise.
245	 * The uniqueness demanded here is the corpus discipline — exactly one served
246	 * module may carry it, exactly once — so overwriting it in place cannot be
247	 * absorbed by a second copy elsewhere in the bundle.
248	 */
249	async function semanticMutation(
250		laneRoot: string,
251		behaviorDigest: string,
252	): Promise<WitnessAngularTinyTranslatorMutation> {
253		const expected = Buffer.from(TINY_TRANSLATOR_MUTATION_SEAM);
254		const candidates: Array<{ path: string; offset: number }> = [];
255		for (const path of await files(laneRoot)) {
256			const bytes = await readFile(path);
257			const offset = bytes.indexOf(expected);
258			if (offset < 0) continue;
259			if (bytes.lastIndexOf(expected) !== offset)
260				throw new Error('TinyTranslator semantic seam is not unique within its file');
261			candidates.push({ path, offset });
262		}
263		const target = candidates[0];
264		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
265			throw new Error('TinyTranslator semantic seam is not a single served module');
266		const before = await readFile(target.path);
267		const mutated = Buffer.from(before);
268		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
269		const beforeSha256 = sha256(before);
270		const mutatedSha256 = sha256(mutated);
271		let intendedFailure = false;
272		try {
273			await writeFile(target.path, mutated);
274			try {
275				await executeAngularTinyTranslatorWitnessRun({
276					lane: 'migrated',
277					pass: 1,
278					laneRoot,
279					receiptRoot: join(stageRoot, 'mutation-receipt'),
280				});
281			} catch (error) {
282				const message = error instanceof Error ? error.message : String(error);
283				intendedFailure = message.includes(TINY_TRANSLATOR_MUTATION_SEAM);
284			}
285		} finally {
286			await writeFile(target.path, before);
287		}
288		const afterRestoreSha256 = sha256(await readFile(target.path));
289		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
290			throw new Error('TinyTranslator semantic mutation was not exact red and byte-restored');
291		const restored = (await executeAngularTinyTranslatorWitnessRun({
292			lane: 'migrated',
293			pass: 1,
294			laneRoot,
295			receiptRoot: join(stageRoot, 'restoration-receipt'),
296		})) as WitnessAngularTinyTranslatorRun;
297		const restoredBehaviorDigest = witnessAngularTinyTranslatorBehaviorDigest(restored);
298		if (restoredBehaviorDigest !== behaviorDigest)
299			throw new Error('TinyTranslator restored browser behavior differs');
300		return {
301			failure: 'witness-semantic-assertion',
302			intendedFailure: true,
303			lane: 'migrated',
304			seam: TINY_TRANSLATOR_MUTATION_SEAM,
305			path: relative(laneRoot, target.path),
306			offset: target.offset,
307			beforeSha256,
308			mutatedSha256,
309			afterRestoreSha256,
310			restoredByteIdentically: true,
311			restoredRun: 'pass',
312			restoredBehaviorDigest,
313		};
314	}
