338		return await Promise.all(
339			ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.map(async (pinned) => {
340				const bytes = await readFile(join(root, pinned.path));
341				const value = JSON.parse(bytes.toString('utf8')) as {
342					schemaVersion?: unknown;
