344				};
345				if (
346					value.schemaVersion !== pinned.schemaVersion ||
347					value.digest !== pinned.digest ||
348					sha256(bytes) !== pinned.sha256
349				)
350					throw new Error(
351						`TinyTranslator bound build receipt identity differs: ${pinned.path}`,
352					);
353				return { ...pinned };
354			}),
355		);
356	}
357	
358	export async function runWitnessAngularTinyTranslator(): Promise<WitnessAngularTinyTranslatorReceipt> {
359		if (
360			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
361			process.env.NPM_CONFIG_OFFLINE !== 'true'
362		)
363			throw new Error('TinyTranslator Witness requires dual offline controls');
364		if (await exists(witnessEvidence))
365			throw new Error('TinyTranslator Witness output collision');
366		const provenance = await verifyLinkedWitnessProvenance(root);
367		const canonicalReceipts = await bindCanonicalReceipts();
368		const lanes = await stageInputs();
369		const runs = await executeRuns(lanes);
370		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
371		const baseline = runs.find((entry) => entry.lane === 'baseline')!;
372		const migrated = runs.find((entry) => entry.lane === 'migrated')!;
373		const artifacts = join(fixtureEvidence, 'witness-artifacts');
374		await mkdir(artifacts, { recursive: true });
375		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
376			flag: 'wx',
377		});
378		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
379			flag: 'wx',
380		});
381		const receipt: WitnessAngularTinyTranslatorReceipt = {
382			schemaVersion: WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
383			result: 'pass',
384			fixture: ANGULAR_TINY_TRANSLATOR_FIXTURE,
385			source: ANGULAR_TINY_TRANSLATOR_SOURCE,
386			provenance,
387			canonicalReceipts,
388			runs,
389			mutation,
390			consoleErrors: {
391				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.baseline],
392				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.migrated],
393			},
394			failedRequests: {
395				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.baseline],
396				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.migrated],
397			},
398			mockedSeams: {
399				baseline: [...baseline.mockedNonLoopbackSeams.category],
400				migrated: [...migrated.mockedNonLoopbackSeams.category],
401			},
402			fontSeamDifference: WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
403			serviceWorkerAttempt: WITNESS_ANGULAR_TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
404			migratedLaneChain: ANGULAR_TINY_TRANSLATOR_MIGRATED_LANE_CHAIN,
405			migrationFindings: WITNESS_ANGULAR_TINY_TRANSLATOR_MIGRATION_FINDINGS,
406			amendments: WITNESS_ANGULAR_TINY_TRANSLATOR_RECORDED_AMENDMENTS,
407			/**
408			 * The arbitration outcome, read out of the runs rather than declared beside
409			 * them: the obligation the build lanes handed this proof is the one the
410			 * schema publishes, and the numbers are the parse both lanes measured.
411			 */
412			fileReaderArbitration: {
413				state: 'arbitrated-declared-difference',
414				obligation: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS.journeyObligations[0]!,
415				outcome: 'identical-parse-in-both-lanes',
416				parsedUnits: baseline.applicationJourney.fileReaderParity.parsedUnits,
417				parsedDigest: baseline.applicationJourney.fileReaderParity.parsedDigest,
418				inBehaviorDigest: true,
419			},
420			matIconDegradations: {
421				baseline: baseline.applicationJourney.matIcon,
422				migrated: migrated.applicationJourney.matIcon,
423			},
424			renderedStyleParity: {
425				state: 'measured-resolved-styles-with-declared-differences',
426				probes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES.length,
427				declaredDifferences: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
428				otherProbesAgree: true,
429			},
430			fileInput: {
431				surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
432				fixture: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
433				rule: WITNESS_FILE_INPUT_LOAD_RULE,
434			},
435			downloads: {
436				surface: WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
437				rule: WITNESS_DOWNLOAD_CAPTURE_RULE,
438				captured: runs.map((entry) => ({
439					lane: entry.lane,
440					pass: entry.pass,
441					files: [...entry.downloadCaptures.captured],
442				})),
443			},
444			persistence: {
445				store: 'browser-local-storage',
446				backend: 'none',
447				stubbed: false,
448				survivesOnlineReload: true,
449			},
450			routeShape: WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
451			scrollAbsence: runs[0]!.scrollAbsence,
452			accommodations: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
453			readiness: {
454				angularLineage: { ready: 1, total: 4, counted: false },
455				overall: { ready: 3, total: 12 },
456			},
457			locality: {
458				mode: 'offline',
459				successfulNonLoopback: 0,
460				osWideIsolation: false,
461				mockedNonLoopbackSeams: migrated.mockedNonLoopbackSeams.category.length,
462			},
463			nonclaims: [...WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS],
464			integrity: { algorithm: 'sha256', canonicalDigest: '' },
465		};
466		receipt.integrity.canonicalDigest = witnessAngularTinyTranslatorDigest(receipt);
467		parseWitnessAngularTinyTranslatorReceipt(receipt);
468		await mkdir(witnessEvidence, { recursive: true });
469		const canonical = canonicalize(receipt);
470		/**
471		 * The companion is rendered from the receipt as PUBLISHED rather than from
472		 * the object in memory: canonicalization sorts keys, so a companion rendered
473		 * from the in-memory object would disagree with the same companion rendered
474		 * from the file, and `verify` — which only ever has the file — would be
475		 * right to reject it.
476		 */
477		const published = parseWitnessAngularTinyTranslatorReceipt(JSON.parse(canonical));
478		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
479		await writeFile(
480			join(witnessEvidence, 'receipt.md'),
481			renderWitnessAngularTinyTranslatorReceipt(published),
482			{ flag: 'wx' },
483		);
484		return published;
485	}
486	
487	export async function verifyWitnessAngularTinyTranslator(
488		output = witnessEvidence,
489	): Promise<WitnessAngularTinyTranslatorReceipt> {
490		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
491		const receipt = parseWitnessAngularTinyTranslatorReceipt(
492			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
493		);
494		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
495			throw new Error('TinyTranslator linked Witness provenance differs');
496		for (const bound of receipt.canonicalReceipts)
497			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
498				throw new Error(`TinyTranslator bound build receipt bytes drifted: ${bound.path}`);
499		if (
500			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
501			renderWitnessAngularTinyTranslatorReceipt(receipt)
502		)
503			throw new Error('TinyTranslator human Witness receipt differs');
504		const serialized = canonicalize(receipt);
505		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
506			throw new Error('TinyTranslator receipt leaks host identity');
507		return receipt;
508	}
509	
510	export async function main(args = process.argv.slice(2)): Promise<void> {
511		const publishIndex = args.indexOf('--publish');
512		const verifyIndex = args.indexOf('--verify');
513		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
514			const output = resolve(root, args[publishIndex + 1]!);
515			if (output !== witnessEvidence) throw new Error('TinyTranslator publish path differs');
516			const receipt = await runWitnessAngularTinyTranslator();
517			process.stdout.write(
518				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
519			);
520			return;
521		}
522		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
523			const receipt = await verifyWitnessAngularTinyTranslator(
524				resolve(root, args[verifyIndex + 1]!),
525			);
526			process.stdout.write(
527				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
528			);
529			return;
530		}
531		throw new Error(
532			'TinyTranslator Witness runner requires --run-twice --publish <dir> or --verify <dir>',
533		);
534	}
535	
536	if (basename(process.argv[1] ?? '') === 'angular-tiny-translator-run.ts')
537		main().catch((error: unknown) => {
538			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
539			process.exitCode = 1;
540		});
