		renderWitnessAngularJiraCloneReceipt(receipt)
	)
		throw new Error('Angular jira-clone human Witness receipt differs');
	return {
		valid: true as const,
		digest: receipt.integrity.canonicalDigest,
		artifacts: 0,
		receipt,
	};
}

